function ReportsPanel({data}:any){const consultations=Array.isArray(data.consultations)?data.consultations:[],questions=Array.isArray(data.questions)?data.questions:[],reviews=Array.isArray(data.reviews)?data.reviews:[],orders=Array.isArray(data.orders)?data.orders:[],statuses:string[]=[...new Set<string>(consultations.map((item:any)=>String(item.status||"pending")))],percentage=(part:number,total:number)=>total?`${new Intl.NumberFormat("fa-IR",{maximumFractionDigits:1}).format(part*100/total)}٪`:"بدون داده";return <><div className="metric-grid"><Metric label="نرخ تکمیل مشاوره" value={percentage(consultations.filter((item:any)=>item.status==="completed").length,consultations.length)} icon={<CheckCircle2/>}/><Metric label="نرخ پاسخ پرسش" value={percentage(questions.filter((item:any)=>item.status==="answered").length,questions.length)} icon={<HelpCircle/>}/><Metric label="نظر تأییدشده" value={reviews.filter((item:any)=>item.status==="approved").length} icon={<Star/>}/><Metric label="سفارش پرداخت‌شده" value={orders.filter((item:any)=>item.status==="paid").length} icon={<WalletCards/>}/></div><div className="dashboard-columns"><DashboardCard title="مشاوره بر اساس نوع"><DataTable columns={["نوع","تعداد"]} rows={["phone","in_person"].map(type=>[translateType(type),consultations.filter((item:any)=>item.type===type).length])}/></DashboardCard><DashboardCard title="مشاوره بر اساس وضعیت"><DataTable columns={["وضعیت","تعداد"]} rows={statuses.map(status=>[<Status key="s" value={status}/>,consultations.filter((item:any)=>String(item.status||"pending")===status).length])}/></DashboardCard></div></>}
