 const marked=new Set(normalized.map((item:any)=>localDateKey(item.eventAt)));
 const minDate=new Date(now-today.getTimezoneOffset()*60000).toISOString().slice(0,16);
 async function addSlot(e:FormEvent<HTMLFormElement>){e.preventDefault();if(!session)return;const form=e.currentTarget,formData=new FormData(form),startsAt=String(formData.get("startsAt")||"");if(!startsAt){setError("تاریخ و ساعت را انتخاب کنید");return}setBusy(true);setError("");try{await request("/lawyer/action",{method:"POST",body:JSON.stringify({action:"add-slot",startsAt:new Date(startsAt).toISOString(),consultationType:formData.get("consultationType")})},session.token);form.reset();setShowForm(false);notify?.("زمان آزاد در تقویم ثبت شد");await refresh?.()}catch(reason){setError((reason as Error).message)}finally{setBusy(false)}}
